import{_ as a,C as o,o as i,c as n,E as r,a2 as s}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"Every Agent Passed Its Check. Why Can the System Still Be Unsafe?","description":"","frontmatter":{"title":"Every Agent Passed Its Check. Why Can the System Still Be Unsafe?","date":"2026-09-07","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当每个数字员工都通过自己的局部安全检查时，还需要什么证据才能说明不可信影响无法沿消息、共享状态、委派权限或恢复路径抵达受保护效果？","summary":"A systematization covering 197 multi-agent security works makes a critical distinction explicit: local passes do not establish end-to-end safety. The security object is the complete authority-to-effect path, including observation coverage, intervention reach, trust assumptions, alternate routes, and recovery after propagation.","sources":["research/analysis/Q-20260907-01-authority-to-effect-path-closure.md"],"item_id":"Q-20260907-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-07-local-safety-does-not-close-path-editorial-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-09-07-local-safety-does-not-close-path.md","filePath":"en/digital-employee/2026-09-07-local-safety-does-not-close-path.md","lastUpdated":1788926442000}'),l={name:"en/digital-employee/2026-09-07-local-safety-does-not-close-path.md"};function c(d,e,h,u,p,m){const t=o("ArticleCover");return i(),n("div",null,[r(t,{image:"/assets/covers/daily-2026-09-07-local-safety-does-not-close-path-editorial-v2.webp",kicker:"Digital Employee · Daily Research",title:"Every Agent Passed Its Check. Why Can the System Still Be Unsafe?",summary:"A systematization covering 197 multi-agent security works makes a critical distinction explicit: local passes do not establish end-to-end safety. The security object is the complete authority-to-effect path, including observation coverage, intervention reach, trust assumptions, alternate routes, and recovery after propagation.",version:"Q-20260907-01",status:"Daily Runtime V5 · 2026-09-07",languageHref:"/zh/digital-employee/2026-09-07-local-safety-does-not-close-path",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="every-agent-passed-its-check-why-can-the-system-still-be-unsafe" tabindex="-1">Every Agent Passed Its Check. Why Can the System Still Be Unsafe? <a class="header-anchor" href="#every-agent-passed-its-check-why-can-the-system-still-be-unsafe" aria-label="Permalink to &quot;Every Agent Passed Its Check. Why Can the System Still Be Unsafe?&quot;">​</a></h1><p>Imagine a multi-agent system in which every local check succeeds. The sender passes an input gate. An intermediary reads only authorized data. A tool call is permitted by policy. The final executor also remains within its declared scope. Step by step, everything looks valid.</p><p>Now change one detail: low-authority information enters shared memory, gets compressed into a summary that no longer carries its origin, and later influences a high-authority agent that invokes a privileged tool. Every local transition can still appear compliant while the final effect violates the purpose of the original authorization.</p><p>That is the core trap in multi-agent security: <strong>treating individually safe workers as evidence that the overall system is safe.</strong> A same-day research object based on a systematization of 197 multi-agent security works, plus a separate audit of 44 evaluation works, suggests a different security object. What matters is not only whether each node behaved locally, but whether the complete path from an influence origin to a protected effect is actually closed.</p><h2 id="local-compliance-proves-a-local-proposition" tabindex="-1">Local compliance proves a local proposition <a class="header-anchor" href="#local-compliance-proves-a-local-proposition" aria-label="Permalink to &quot;Local compliance proves a local proposition&quot;">​</a></h2><p>A worker-level check usually answers a narrow question: was this message allowed, was this file in scope, did this model output trigger a rule, was this tool target authorized? Those checks matter, but multi-agent effects are relational.</p><p>Influence may travel through an original message, shared state, a summary, an intermediate judgment, delegated authority, and finally a tool action. If provenance is lost, meaning changes at a handoff, or a low-authority input becomes wrapped in a high-authority agent&#39;s conclusion, the resulting action can be locally valid yet globally unsafe.</p><p>Local safety therefore answers, &quot;Was this hop allowed under its local rule?&quot; System safety must also answer, &quot;Where did the influence originate, what transformed it, which principals carried it across authority boundaries, and why did it become eligible to produce this effect?&quot;</p><p>These are different proof obligations.</p><h2 id="five-evidence-gaps-exposed-by-the-systematization" tabindex="-1">Five evidence gaps exposed by the systematization <a class="header-anchor" href="#five-evidence-gaps-exposed-by-the-systematization" aria-label="Permalink to &quot;Five evidence gaps exposed by the systematization&quot;">​</a></h2><p>The primary study organizes multi-agent security around cross-principal execution paths, six interaction interfaces, and eight recurring attack paths. It evaluates defenses through fields including path target, observation, intervention, trust boundary, and recovery.</p><p>The practical value of those fields is that they prevent one positive local test from silently standing in for the whole route:</p><table tabindex="0"><thead><tr><th>Evidence question</th><th>What it actually establishes</th><th>What a local PASS does not establish</th></tr></thead><tbody><tr><td>Path target</td><td>Which system-level risk and route segment the control intends to break</td><td>That no alternate route exists</td></tr><tr><td>Observation</td><td>Which messages, principals, state, or traces the control can see</td><td>That unseen routes are absent</td></tr><tr><td>Intervention</td><td>What the control can block, rewrite, quarantine, revoke, or repair</td><td>That seeing a problem is enough to stop it</td></tr><tr><td>Trust boundary</td><td>Which identities, logs, topology, and membership assumptions must remain valid</td><td>That implicit trust is harmless</td></tr><tr><td>Recovery</td><td>How derivative state and authority are found, repaired, revoked, and re-verified</td><td>That containing the original source restores the system</td></tr></tbody></table><p>This is also why &quot;we blocked the malicious sender&quot; can be only the middle of an incident. Once influence has propagated, the system may still contain derived memories, artifacts, credentials, delegated rights, spawned principals, or external effects created under that influence.</p><h2 id="the-security-claim-should-bind-an-origin-to-effect-lineage" tabindex="-1">The security claim should bind an origin-to-effect lineage <a class="header-anchor" href="#the-security-claim-should-bind-an-origin-to-effect-lineage" aria-label="Permalink to &quot;The security claim should bind an origin-to-effect lineage&quot;">​</a></h2><p>A governed runtime can represent a minimal provenance-preserving chain:</p><p><code>influence origin → admitted message or artifact → state and principal transformations → delegated authority → protected effect</code></p><p>The point is not to preserve every hidden reasoning token. It is to preserve enough durable evidence to answer responsibility and authorization questions: who introduced the influence, which transformations changed or preserved its meaning, which intermediary carried it into a new authority domain, what delegated right made the final effect reachable, and which parts of the route the current controls could actually observe and interrupt.</p><p>This changes the meaning of a tool-permission check. The runtime should not ask only whether &quot;Agent X may call Tool Y.&quot; It should also ask how the authority for this particular call became reachable. If a privileged call was shaped indirectly by a low-authority source through shared state, a compliant tool invocation does not automatically imply a compliant influence path.</p><p>This does not require one omniscient central monitor. Centralized visibility can itself create privacy, concentration, and control-plane risk. The governance requirement is explicit coverage and explicit blind spots, not a mandatory architecture.</p><h2 id="alternate-routes-are-the-hard-part" tabindex="-1">Alternate routes are the hard part <a class="header-anchor" href="#alternate-routes-are-the-hard-part" aria-label="Permalink to &quot;Alternate routes are the hard part&quot;">​</a></h2><p>Blocking one known path does not prove that a protected effect is unreachable. If the same influence can travel through another set of principals, another shared-state channel, another tool permission, or a recovery replay, the path is not closed.</p><p>System-level safety therefore needs alternate-route awareness. When membership, topology, routing, or tool permissions change, does the old safety judgment still hold? Which routes are directly observed, and which are merely assumed not to exist? If one relationship is removed, does the modified system still preserve a meaningful security proposition that can be compared with the original?</p><p>The same-day analysis treats relation-removal counterfactuals as a bounded tool. Where the task remains meaningful, removing a relationship can expose a hidden assumption that &quot;this was the only route.&quot; Such a test does not automatically prove causality, but it can reveal incomplete closure claims.</p><h2 id="containment-is-not-recovery" tabindex="-1">Containment is not recovery <a class="header-anchor" href="#containment-is-not-recovery" aria-label="Permalink to &quot;Containment is not recovery&quot;">​</a></h2><p>A crucial distinction in multi-agent incidents is often compressed into one status: containment and recovery are not the same state.</p><p>Containment asks whether influence can continue to spread. Recovery asks whether already affected memories, artifacts, credentials, delegated rights, principals, and effects have been identified, revoked or repaired, and re-verified as trustworthy. If the original sender is isolated but the system continues to consume a contaminated summary or delegated credential, the influence remains operational.</p><p>A mature incident model should therefore be able to say, &quot;The source is contained, but derivative state has not yet been recovered.&quot; Preserving that uncertainty is more accurate than prematurely returning the system to a green state.</p><h2 id="does-more-logging-automatically-mean-more-safety" tabindex="-1">Does more logging automatically mean more safety? <a class="header-anchor" href="#does-more-logging-automatically-mean-more-safety" aria-label="Permalink to &quot;Does more logging automatically mean more safety?&quot;">​</a></h2><p>No. Full traceability has costs: privacy exposure, storage, centralized control risk, and the possibility that provenance records themselves can be forged or contaminated. The goal should be minimum sufficient evidence, not indiscriminate collection.</p><p>Likewise, a global observer is not automatically superior to local controls. A global view may cover more routes but depend on coarser data and stronger trust assumptions. Local controls may have richer context but miss alternate paths. What must remain durable is the declared observation boundary, intervention reach, trust dependency, and residual blind spot.</p><h2 id="the-engineering-consequence-for-digital-employees" tabindex="-1">The engineering consequence for digital employees <a class="header-anchor" href="#the-engineering-consequence-for-digital-employees" aria-label="Permalink to &quot;The engineering consequence for digital employees&quot;">​</a></h2><p>For long-lived digital employees, several facts should survive beyond the model context:</p><ul><li>provenance and authorization context across messages, summaries, shared state, and handoffs;</li><li>intermediate principals and delegation relationships behind privileged effects;</li><li>observation and intervention coverage for system-level controls;</li><li>safety judgments that must be revalidated after membership, topology, routing, or permission changes;</li><li>derivative artifacts, credentials, authority, and principals that remain unresolved after containment.</li></ul><p>None of this produces a universal safety architecture. It moves the proof obligation to the correct layer: <strong>do not ask only whether each agent passed its own check; ask whether the complete authority-to-effect path is observable and interruptible under stated trust assumptions, whether alternate routes have been assessed, and whether propagated state can actually be recovered.</strong></p><h2 id="evidence-boundary-and-open-questions" tabindex="-1">Evidence boundary and open questions <a class="header-anchor" href="#evidence-boundary-and-open-questions" aria-label="Permalink to &quot;Evidence boundary and open questions&quot;">​</a></h2><p>The current evidence is a systematization and evaluation audit, not an end-to-end proof of any production runtime. A 197-work corpus provides broad coverage but cannot exhaust fast-changing deployment practice, and the five evidence dimensions are an analytical framework rather than a mechanically verified universal standard.</p><p>Open questions include how to preserve trustworthy provenance through context compression without over-collecting sensitive data; whether dynamic systems can test alternate-route closure online; which protected effects require prevention rather than compensating recovery; and how to obtain sufficient path evidence without building a high-risk omniscient control plane.</p><p><strong>Evidence and sources:</strong></p><ul><li><a href="https://arxiv.org/html/2609.00595v1" target="_blank" rel="noreferrer">Multi-Agent Systems Security Systematization</a></li></ul>',40))])}const f=a(l,[["render",c]]);export{g as __pageData,f as default};
